import java.util.*;
import java.io.*;

public class Main {
    static int[] messageTimes(int n, int[][] edges) {
        // Write your solution here
        // Return {parallelTime, sequentialTime}
        return new int[]{0, 0};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[][] edges = new int[Math.max(0, n - 1)][2];
        for (int i = 0; i < n - 1; i++) {
            in.nextToken(); edges[i][0] = (int) in.nval;
            in.nextToken(); edges[i][1] = (int) in.nval;
        }
        int[] res = messageTimes(n, edges);
        System.out.println(res[0] + " " + res[1]);
    }
}
